def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 548.8464074053809  # OPT_PARAM: {"initial": 548.8464074053809, "min": 400, "max": 700, "type": "float"}
    smoothing_factor = 0.4201773336488429  # OPT_PARAM: {"initial": 0.4201773336488429, "min": 0.1, "max": 1.0, "type": "float"}
    safety_stock = 98.84640740538053  # OPT_PARAM: {"initial": 98.84640740538053, "min": 50, "max": 200, "type": "float"}

    projected_inventory = on_hand_inventory + sum(pipeline_orders)
    target_inventory = base_stock + safety_stock
    order_amount = max(0, smoothing_factor * (target_inventory - projected_inventory))
    return order_amount
